// All inputs are generated by tools/testlab/backend.py. This package never
// reads .env, user connection files, real credentials or a business database.
type fixture struct {
	BaseURLs             []string                         `json:"base_urls"`
	DatabaseURL          string                           `json:"database_url"`
	MigrationDatabaseURL string                           `json:"migration_database_url"`
	Environment          string                           `json:"environment"`
	OtherEnvironment     string                           `json:"other_environment"`
	ModelID              string                           `json:"model_id"`
	PostgresContainer    string                           `json:"postgres_container"`
	Owner                string                           `json:"owner"`
	Admin                struct{ Email, Password string } `json:"admin"`
}

func readFixture(t *testing.T, requireHTTP bool) fixture {
	t.Helper()
	if os.Getenv("AIOPS_TESTLAB_BACKEND_ENABLED") != "dedicated-temp-container" {
		t.Skip("explicit disposable backend testlab opt-in required")
	}
	name := os.Getenv("AIOPS_TESTLAB_BACKEND_FIXTURE")
	info, err := os.Lstat(name)
	if err != nil || !info.Mode().IsRegular() || info.Mode().Perm() != 0600 {
		t.Fatal("generated 0600 regular backend fixture required")
	}
	raw, err := os.ReadFile(name)
	if err != nil {
		t.Fatal("cannot read backend fixture")
	}
	var f fixture
	if json.Unmarshal(raw, &f) != nil {
		t.Fatal("invalid generated backend fixture JSON")
	}
	guardDSN(t, f.DatabaseURL, "aiops_testlab_app")
	if f.MigrationDatabaseURL == "" {
		f.MigrationDatabaseURL = os.Getenv("TEST_DATABASE_URL")
	}
	guardDSN(t, f.MigrationDatabaseURL, "aiops_testlab")
	if f.PostgresContainer == "" || f.Owner == "" {
		t.Fatal("generated testlab PostgreSQL ownership identity required")
	}
	labels, err := exec.CommandContext(t.Context(), "docker", "inspect", "--format", "{{json .Config.Labels}}", f.PostgresContainer).Output()
	var owned map[string]string
	if err != nil || json.Unmarshal(labels, &owned) != nil || owned["aiops.testlab.owner"] != f.Owner {
		t.Fatal("database container lacks the exact generated testlab ownership label")
	}
	if requireHTTP {
		if len(f.BaseURLs) != 2 || f.Environment == "" || f.OtherEnvironment == "" || f.Environment == f.OtherEnvironment || f.Admin.Email == "" || f.Admin.Password == "" {
			t.Fatal("two instances, two environments and disposable account required")
		}
		for _, rawURL := range f.BaseURLs {
			u, err := url.Parse(rawURL)
			if err != nil || u.Hostname() != "127.0.0.1" || u.Port() == "" || u.User != nil || (u.Scheme != "http" && u.Scheme != "https") || u.RawQuery != "" || u.Path != "" {
				t.Fatal("backend endpoint must be explicit loopback origin")
			}
		}
	}
	return f
}

func guardDSN(t *testing.T, raw, database string) {
	t.Helper()
	u, err := url.Parse(raw)
	if err != nil || u.Hostname() != "127.0.0.1" || u.Port() == "" || u.Path != "/"+database || (u.Scheme != "postgres" && u.Scheme != "postgresql") {
		t.Fatal("test database must be the explicit disposable loopback database")
	}
}

func isolatedStore(t *testing.T, f fixture) (*store.Store, string) {
	t.Helper()
	ctx := t.Context()
	admin, err := pgxpool.New(ctx, f.MigrationDatabaseURL)
	if err != nil {
		t.Fatal("test database pool unavailable")
	}
	schema := "backend_test_" + store.ID()
	quoted := pgx.Identifier{schema}.Sanitize()
	if _, err := admin.Exec(ctx, "CREATE SCHEMA "+quoted); err != nil {
		admin.Close()
		t.Fatal(err)
	}
	cfg, err := pgxpool.ParseConfig(f.MigrationDatabaseURL)
	if err != nil {
		t.Fatal("test pool config invalid")
	}
	cfg.ConnConfig.RuntimeParams["search_path"] = schema + ",public"
	cfg.MaxConns = 4
	db, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		t.Fatal("test pool unavailable")
	}
	t.Cleanup(func() {
		db.Close()
		if _, err := admin.Exec(context.Background(), "DROP SCHEMA IF EXISTS "+quoted+" CASCADE"); err != nil {
			t.Error(err)
		}
		admin.Close()
	})
	return &store.Store{DB: db}, schema
}

type response struct {
	Status       int
	Header       http.Header
	Data         map[string]any
	Raw          []byte
	Method, Path string
}

var interfaceMu sync.Mutex
var interfaceRunID = store.ID()

func request(t *testing.T, client *http.Client, base, method, path, env string, body any, headers map[string]string) response {
	t.Helper()
	var input io.Reader
	if body != nil {
		raw, err := json.Marshal(body)
		if err != nil {
			t.Fatal(err)
		}
		input = bytes.NewReader(raw)
	}
	ctx := t.Context()
	if ctx.Err() != nil {
		// Go cancels t.Context before Cleanup; restoration still needs a
		// live bounded request context for this test's own writes.
		ctx = context.Background()
	}
	ctx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	r, err := http.NewRequestWithContext(ctx, method, base+path, input)
	if err != nil {
		t.Fatal("test request invalid")
	}
	if body != nil {
		r.Header.Set("Content-Type", "application/json")
	}
	if env != "" {
		r.Header.Set("X-AIOps-Environment", env)
	}
	if method != "GET" && method != "HEAD" {
		r.Header.Set("Origin", base)
	}
	for k, v := range headers {
		r.Header.Set(k, v)
	}
	w, err := client.Do(r)
	if err != nil {
		t.Fatalf("backend HTTP request failed for %s %s: %v", method, path, err)
	}
	defer w.Body.Close()
	raw, err := io.ReadAll(io.LimitReader(w.Body, 4<<20))
	if err != nil {
		t.Fatal("response read failed")
	}
	var data map[string]any
	_ = json.Unmarshal(raw, &data)
	return response{Status: w.StatusCode, Header: w.Header, Data: data, Raw: raw, Method: method, Path: strings.Split(path, "?")[0]}
}

func expect(t *testing.T, r response, want int) {
	t.Helper()
	recordInterface(t, r, want)
	if r.Status != want {
		code := ""
		if e, ok := r.Data["error"].(map[string]any); ok {
			code, _ = e["code"].(string)
		}
		t.Fatalf("HTTP status=%d want=%d error_code=%s", r.Status, want, code)
	}
}

func recordInterface(t *testing.T, r response, want int) {
	t.Helper()
	if os.Getenv("AIOPS_TESTLAB_BACKEND_FIXTURE") == "" {
		return
	}
	path := r.Path
	parts := strings.Split(path, "/")
	for i, p := range parts {
		if strings.HasPrefix(p, "CV-") || strings.HasPrefix(p, "INV-") || strings.HasPrefix(p, "INC-") || (i >= 4 && len(p) == 32) {
			parts[i] = "{id}"
		}
	}
	path = strings.Join(parts, "/")
	scenario := "normal"
	switch r.Status {
	case 401, 403:
		scenario = "authorization"
	case 400, 404, 412, 422, 428:
		scenario = "boundary"
	case 409:
		scenario = "idempotency"
	case 500, 501, 502, 503, 504:
		scenario = "failure"
	}
	if r.Status == 200 && r.Method == "POST" && strings.Contains(t.Name(), "Idempotency") && (r.Path == "/api/v1/incidents" || strings.HasSuffix(r.Path, "/status")) {
		scenario = "idempotency"
	}
	status := "passed"
	if r.Status != want {
		status = "failed"
	}
	raw, _ := json.Marshal(map[string]any{"run_id": interfaceRunID, "call_id": store.ID(), "method": r.Method, "path": path, "scenario": scenario, "scenarios": []string{scenario}, "expected": want, "actual": r.Status, "status": status, "test_name": t.Name(), "registration_evidence": r.Status >= 200 && r.Status < 300 || r.Status == 404 && r.Data["error"] != nil, "evidence": "formal dual cmd/aiops instances; real disposable PostgreSQL"})
	interfaceMu.Lock()
	defer interfaceMu.Unlock()
	f, err := os.OpenFile(filepath.Join(filepath.Dir(os.Getenv("AIOPS_TESTLAB_BACKEND_FIXTURE")), "interface-results.jsonl"), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0600)
	if err != nil {
		t.Error("cannot record HTTP interface evidence")
		return
	}
	defer f.Close()
	if _, err = f.Write(append(raw, '\n')); err != nil {
		t.Error("cannot record HTTP interface evidence")
	}
}

func httpClient() *http.Client {
	return &http.Client{Timeout: 15 * time.Second, CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}
}
